def build_gaussian_model(
    deterministic_configuration,
    *,
    device,
):
    section = (
        deterministic_configuration[
            "model"
        ]
    )

    return (
        GaussianTrajectoryGRU(
            target_hidden_dim=int(
                section[
                    "target_hidden_dim"
                ]
            ),

            neighbor_hidden_dim=int(
                section[
                    "neighbor_hidden_dim"
                ]
            ),

            map_hidden_dim=int(
                section[
                    "map_hidden_dim"
                ]
            ),

            fusion_hidden_dim=int(
                section[
                    "fusion_hidden_dim"
                ]
            ),

            use_neighbors=True,
            use_map=True,
        )
        .to(device)
    )
